arguments.file_text:
:root {
  --bg: #0a0a0c;
  --bg-elev: #121217;
  --bg-elev-2: #1a1a22;
  --border: #26262f;
  --border-strong: #353542;
  --text: #f5f5f7;
  --text-dim: #9a9aa6;
  --text-muted: #6b6b76;
  --accent: #d4ff3a;
  --accent-2: #ff5b3a;
  --accent-soft: rgba(212, 255, 58, 0.12);
  --gold: #c9a96a;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  --font-display: "Fraunces", "Times New Roman", Georgia, serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  scroll-behavior: smooth;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
img { display: block; max-width: 100%; }

.container {
  width: 100%;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 28px;
}

/* ===== Announcement Bar ===== */
.announce {
  background: linear-gradient(90deg, #0e0e12, #16161d, #0e0e12);
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
}
.announce-inner {
  display: flex; justify-content: space-between; align-items: center;
  height: 36px;
}
.announce-center { color: var(--text); }
.announce-center b { color: var(--accent); font-weight: 600; }
.announce-links { display: flex; gap: 22px; }
.announce-links a:hover { color: var(--text); }

/* ===== Header ===== */
.header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(10, 10, 12, 0.85);
  backdrop-filter: saturate(160%) blur(14px);
  -webkit-backdrop-filter: saturate(160%) blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 72px;
  gap: 24px;
}
.logo {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -0.02em;
  display: flex; align-items: center; gap: 6px;
}
.logo-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); display: inline-block; }
.nav { display: flex; gap: 28px; justify-self: center; }
.nav a {
  font-size: 14px; font-weight: 500;
  color: var(--text-dim);
  position: relative; padding: 6px 0;
  transition: color 0.18s;
}
.nav a:hover, .nav a.active { color: var(--text); }
.nav a.active::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -2px;
  height: 2px; background: var(--accent); border-radius: 2px;
}
.header-actions { display: flex; gap: 6px; justify-self: end; align-items: center; }
.icon-btn {
  width: 40px; height: 40px; display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--text-dim);
  transition: background 0.15s, color 0.15s;
  position: relative;
}
.icon-btn:hover { background: var(--bg-elev-2); color: var(--text); }
.icon-btn .badge {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: #0a0a0c;
  font-size: 10px; font-weight: 700;
  min-width: 18px; height: 18px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  padding: 0 5px;
}

/* ===== Hero ===== */
.hero {
  padding: 28px 0 80px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 28px;
  min-height: 600px;
}
.hero-main {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background:
    radial-gradient(circle at 20% 80%, rgba(212, 255, 58, 0.18), transparent 50%),
    radial-gradient(circle at 80% 10%, rgba(255, 91, 58, 0.18), transparent 50%),
    linear-gradient(160deg, #1c1c26 0%, #0d0d12 100%);
  padding: 48px;
  display: flex; flex-direction: column; justify-content: space-between;
  border: 1px solid var(--border);
}
.hero-tag {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--accent); width: fit-content;
  padding: 7px 14px; border-radius: 999px;
  background: var(--accent-soft);
  border: 1px solid rgba(212, 255, 58, 0.25);
}
.hero-tag::before { content: ""; width: 6px; height: 6px; background: var(--accent); border-radius: 50%; }
.hero-title {
  font-family: var(--font-display);
  font-size: clamp(48px, 6vw, 84px);
  font-weight: 500;
  line-height: 0.96;
  letter-spacing: -0.035em;
  margin-top: 24px;
  margin-bottom: 16px;
}
.hero-title em { font-style: italic; color: var(--accent); font-weight: 400; }
.hero-sub { color: var(--text-dim); max-width: 460px; font-size: 16px; }
.hero-cta-row { display: flex; gap: 12px; margin-top: 32px; align-items: center; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600; font-size: 14px;
  transition: transform 0.15s, background 0.15s, color 0.15s;
}
.btn-primary { background: var(--accent); color: #0a0a0c; }
.btn-primary:hover { background: #e2ff5a; transform: translateY(-1px); }
.btn-ghost {
  border: 1px solid var(--border-strong); color: var(--text);
  background: rgba(255, 255, 255, 0.02);
}
.btn-ghost:hover { background: var(--bg-elev-2); border-color: var(--text-muted); }
.hero-meta {
  display: flex; gap: 32px; align-items: center;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  margin-top: 24px;
}
.hero-meta-item .num {
  font-family: var(--font-display);
  font-size: 32px; font-weight: 500; line-height: 1;
  color: var(--text);
}
.hero-meta-item .label {
  font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--text-muted); margin-top: 6px;
}
.hero-side { display: grid; grid-template-rows: 1.4fr 1fr; gap: 28px; }
.hero-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 28px;
  min-height: 180px;
}
.hero-card.card-a {
  background:
    linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.85) 100%),
    url("https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=800&auto=format&fit=crop&q=80") center/cover;
}
.hero-card.card-b {
  background:
    linear-gradient(180deg, transparent 20%, rgba(0,0,0,0.85) 100%),
    url("https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=800&auto=format&fit=crop&q=80") center/cover;
}
.hero-card-eyebrow {
  font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase;
  color: var(--accent); margin-bottom: 8px;
}
.hero-card-title {
  font-family: var(--font-display);
  font-size: 26px; font-weight: 500; line-height: 1.05;
  letter-spacing: -0.02em;
  margin-bottom: 14px;
}
.hero-card .arrow-link {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; color: var(--text); font-weight: 600;
}
.hero-card .arrow-link:hover { color: var(--accent); }

/* ===== Section header ===== */
.section { padding: 56px 0; }
.section-head {
  display: flex; align-items: end; justify-content: space-between;
  margin-bottom: 32px; gap: 24px; flex-wrap: wrap;
}
.section-eyebrow {
  font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase;
  color: var(--accent); margin-bottom: 12px;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(32px, 4vw, 48px);
  font-weight: 500; line-height: 1; letter-spacing: -0.025em;
  max-width: 640px;
}
.section-title em { font-style: italic; color: var(--text-dim); font-weight: 400; }
.section-actions { display: flex; gap: 8px; align-items: center; }

/* ===== Category Tabs ===== */
.tabs {
  display: flex; gap: 6px; flex-wrap: wrap;
  padding: 6px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 999px;
  width: fit-content;
}
.tab {
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 13px; font-weight: 500;
  color: var(--text-dim);
  transition: all 0.15s;
}
.tab:hover { color: var(--text); }
.tab.active { background: var(--text); color: var(--bg); }

/* ===== Product grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s;
  display: flex; flex-direction: column;
}
.product-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-strong);
}
.product-img {
  position: relative;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  background: linear-gradient(135deg, #1e1e28, #0e0e12);
}
.product-img img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.5s;
}
.product-card:hover .product-img img { transform: scale(1.06); }
.product-tag {
  position: absolute; top: 12px; left: 12px;
  font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase;
  background: var(--bg); color: var(--text);
  padding: 6px 10px; border-radius: 999px;
  font-weight: 600;
  border: 1px solid var(--border);
}
.product-tag.new { background: var(--accent); color: var(--bg); border-color: var(--accent); }
.product-tag.sale { background: var(--accent-2); color: #fff; border-color: var(--accent-2); }
.fav-btn {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(10,10,12,0.7); backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: center;
  color: var(--text); border: 1px solid var(--border);
  transition: all 0.15s;
}
.fav-btn:hover { background: var(--bg); }
.fav-btn.active { color: var(--accent-2); }
.fav-btn.active svg { fill: var(--accent-2); }
.add-overlay {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  background: var(--text); color: var(--bg);
  padding: 11px;
  border-radius: 10px;
  font-weight: 600; font-size: 13px;
  text-align: center;
  opacity: 0; transform: translateY(8px);
  transition: all 0.2s;
}
.product-card:hover .add-overlay { opacity: 1; transform: translateY(0); }
.product-info { padding: 16px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.product-cat {
  font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--text-muted);
}
.product-name {
  font-size: 15px; font-weight: 600; color: var(--text);
  line-height: 1.3;
}
.product-row {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: 8px;
}
.product-price { display: flex; align-items: baseline; gap: 8px; }
.price-now { font-weight: 600; font-size: 16px; }
.price-was { font-size: 13px; color: var(--text-muted); text-decoration: line-through; }
.product-rating {
  display: flex; align-items: center; gap: 4px;
  font-size: 12px; color: var(--text-dim);
}
.product-rating svg { color: var(--accent); }

/* ===== Deals strip ===== */
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 22px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: 36px;
  min-height: 320px;
  display: flex; flex-direction: column; justify-content: space-between;
  border: 1px solid var(--border);
  transition: transform 0.2s;
}
.deal-card:hover { transform: translateY(-3px); }
.deal-a {
  background:
    linear-gradient(135deg, rgba(212,255,58,0.95), rgba(180,220,40,0.85)),
    radial-gradient(circle at 80% 20%, rgba(255,255,255,0.3), transparent 50%);
  color: #0a0a0c;
}
.deal-b {
  background:
    linear-gradient(160deg, #2a1f3a, #181221);
  border: 1px solid #3a2a52;
}
.deal-c {
  background:
    linear-gradient(160deg, #3a1f1a, #1f100c);
  border: 1px solid #5a2a20;
}
.deal-eyebrow {
  font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase;
  font-weight: 700;
  opacity: 0.8;
}
.deal-title {
  font-family: var(--font-display);
  font-size: 38px; font-weight: 500; line-height: 1; letter-spacing: -0.02em;
  margin: 14px 0 12px;
}
.deal-a .deal-title { color: #0a0a0c; }
.deal-desc { font-size: 14px; opacity: 0.75; max-width: 320px; }
.deal-cta {
  display: inline-flex; align-items: center; gap: 8px;
  margin-top: 24px;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600; font-size: 13px;
  background: #0a0a0c; color: var(--text);
  width: fit-content;
}
.deal-a .deal-cta { background: #0a0a0c; color: var(--accent); }
.deal-b .deal-cta { background: var(--accent); color: #0a0a0c; }
.deal-c .deal-cta { background: var(--accent-2); color: #fff; }

.countdown {
  display: flex; gap: 10px; margin-top: 8px;
}
.cd-cell {
  background: rgba(0,0,0,0.2);
  border: 1px solid rgba(0,0,0,0.15);
  border-radius: 8px;
  padding: 8px 12px;
  text-align: center;
  min-width: 56px;
}
.deal-b .cd-cell, .deal-c .cd-cell {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.08);
}
.cd-num {
  font-family: var(--font-display);
  font-size: 24px; font-weight: 600; line-height: 1;
}
.cd-label {
  font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase;
  margin-top: 4px; opacity: 0.7;
}

/* ===== Editorial ===== */
.editorial-feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  margin-bottom: 28px;
}
.editorial-feature-img {
  background: url("https://images.unsplash.com/photo-1483985988355-763728e1935b?w=1200&auto=format&fit=crop&q=80") center/cover;
  min-height: 480px;
}
.editorial-feature-body {
  padding: 56px;
  display: flex; flex-direction: column; justify-content: center;
}
.editorial-feature-body .eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: 18px;
}
.editorial-feature-body h2 {
  font-family: var(--font-display);
  font-size: 46px; font-weight: 500; line-height: 1.05; letter-spacing: -0.025em;
  margin-bottom: 18px;
}
.editorial-feature-body p { color: var(--text-dim); margin-bottom: 28px; max-width: 480px; }
.editorial-author {
  display: flex; align-items: center; gap: 12px;
  margin-top: 28px; padding-top: 28px;
  border-top: 1px solid var(--border);
}
.author-avatar {
  width: 42px; height: 42px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--gold));
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; color: var(--bg);
}
.author-info .name { font-size: 14px; font-weight: 600; }
.author-info .meta { font-size: 12px; color: var(--text-muted); }

.editorial-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px;
}
.editorial-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform 0.2s, border-color 0.2s;
}
.editorial-card:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.editorial-card-img {
  aspect-ratio: 16 / 10;
  overflow: hidden;
}
.editorial-card-img img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s; }
.editorial-card:hover .editorial-card-img img { transform: scale(1.05); }
.editorial-card-body { padding: 22px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.editorial-card .cat {
  font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--accent);
}
.editorial-card h3 {
  font-family: var(--font-display);
  font-size: 22px; font-weight: 500; line-height: 1.2; letter-spacing: -0.015em;
}
.editorial-card .excerpt { color: var(--text-dim); font-size: 14px; }
.editorial-card .meta {
  font-size: 12px; color: var(--text-muted);
  margin-top: auto; padding-top: 14px;
  display: flex; gap: 10px; align-items: center;
}
.editorial-card .meta .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--text-muted); }

/* ===== Categories ===== */
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat-card {
  position: relative;
  aspect-ratio: 3 / 4;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  transition: transform 0.2s;
}
.cat-card:hover { transform: translateY(-3px); }
.cat-card .cat-bg {
  position: absolute; inset: 0;
  background-size: cover; background-position: center;
  transition: transform 0.5s;
}
.cat-card:hover .cat-bg { transform: scale(1.08); }
.cat-card::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.85) 100%);
}
.cat-card .cat-label {
  position: absolute; bottom: 16px; left: 16px; right: 16px;
  z-index: 1;
  font-weight: 600; font-size: 14px;
  display: flex; justify-content: space-between; align-items: center;
}
.cat-card .cat-count { font-size: 11px; color: var(--text-dim); }

/* ===== Brands strip ===== */
.brands {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 32px 0;
}
.brands-inner {
  display: flex; justify-content: space-between; align-items: center;
  gap: 24px; flex-wrap: wrap;
}
.brand-item {
  font-family: var(--font-display);
  font-size: 22px; font-weight: 500; letter-spacing: -0.01em;
  color: var(--text-muted);
  transition: color 0.15s;
  font-style: italic;
}
.brand-item:hover { color: var(--text); }

/* ===== Newsletter ===== */
.newsletter {
  margin: 80px 0;
  padding: 64px;
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 90% 10%, rgba(212,255,58,0.15), transparent 50%),
    radial-gradient(circle at 10% 90%, rgba(255,91,58,0.12), transparent 50%),
    linear-gradient(160deg, #15151d, #0c0c10);
  border: 1px solid var(--border);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px; align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-size: 44px; font-weight: 500; line-height: 1.05; letter-spacing: -0.025em;
  margin-bottom: 14px;
}
.newsletter p { color: var(--text-dim); max-width: 460px; }
.newsletter-form {
  display: flex; gap: 8px;
  background: var(--bg-elev);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 6px;
}
.newsletter-form input {
  flex: 1; background: none; border: none; outline: none;
  color: var(--text); font-family: inherit; font-size: 14px;
  padding: 12px 18px;
}
.newsletter-form input::placeholder { color: var(--text-muted); }
.newsletter-form button {
  background: var(--accent); color: var(--bg);
  font-weight: 600; font-size: 14px;
  padding: 12px 24px;
  border-radius: 999px;
  transition: background 0.15s;
}
.newsletter-form button:hover { background: #e2ff5a; }
.newsletter-perks {
  display: flex; gap: 24px; margin-top: 20px; flex-wrap: wrap;
  font-size: 12px; color: var(--text-muted);
}
.newsletter-perks span { display: inline-flex; align-items: center; gap: 6px; }
.newsletter-perks svg { color: var(--accent); }

/* ===== Footer ===== */
.footer {
  border-top: 1px solid var(--border);
  padding: 64px 0 32px;
  background: var(--bg-elev);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand p { color: var(--text-dim); margin: 14px 0 22px; max-width: 280px; font-size: 14px; }
.footer-socials { display: flex; gap: 8px; }
.footer-socials a {
  width: 38px; height: 38px; border-radius: 50%;
  border: 1px solid var(--border-strong);
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--text-dim);
  transition: all 0.15s;
}
.footer-socials a:hover { background: var(--accent); color: var(--bg); border-color: var(--accent); }
.footer-col h4 {
  font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--text); margin-bottom: 18px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }
.footer-col a { color: var(--text-dim); font-size: 14px; transition: color 0.15s; }
.footer-col a:hover { color: var(--text); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 12px; color: var(--text-muted);
  flex-wrap: wrap; gap: 12px;
}
.payment-icons { display: flex; gap: 8px; align-items: center; }
.payment-icons span {
  background: var(--bg-elev-2); border: 1px solid var(--border);
  padding: 6px 10px; border-radius: 6px; font-size: 11px; font-weight: 700;
  letter-spacing: 0.05em;
}

/* Responsive */
@media (max-width: 1080px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-a { grid-column: 1 / -1; }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 760px) {
  .container { padding: 0 18px; }
  .nav { display: none; }
  .header-inner { grid-template-columns: 1fr auto; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-side { grid-template-rows: auto auto; }
  .hero-main { padding: 32px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-a { grid-column: auto; }
  .editorial-feature { grid-template-columns: 1fr; }
  .editorial-feature-body { padding: 32px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .newsletter { grid-template-columns: 1fr; padding: 36px; }
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
  .announce-links { display: none; }
  .announce-inner { justify-content: center; }
  .hero-meta { gap: 18px; flex-wrap: wrap; }
}

